// Weather - Open-Meteo (keyless). English output, Celsius, human-readable wind.
const input = $input.first().json || {};
const ZAGAZIG = { lat: 30.584138, lon: 31.495866, name: 'Zagazig, Egypt' };

const WMO_EN = {
  0: 'Clear sky',
  1: 'Mainly clear',
  2: 'Partly cloudy',
  3: 'Overcast',
  45: 'Fog',
  48: 'Depositing rime fog',
  51: 'Light drizzle',
  53: 'Moderate drizzle',
  55: 'Dense drizzle',
  56: 'Light freezing drizzle',
  57: 'Dense freezing drizzle',
  61: 'Slight rain',
  63: 'Moderate rain',
  65: 'Heavy rain',
  66: 'Light freezing rain',
  67: 'Heavy freezing rain',
  71: 'Slight snow',
  73: 'Moderate snow',
  75: 'Heavy snow',
  77: 'Snow grains',
  80: 'Slight rain showers',
  81: 'Moderate rain showers',
  82: 'Violent rain showers',
  85: 'Slight snow showers',
  86: 'Heavy snow showers',
  95: 'Thunderstorm',
  96: 'Thunderstorm with slight hail',
  99: 'Thunderstorm with heavy hail',
};

function describe(code) {
  return WMO_EN[code] || ('Weather code ' + code);
}

function windCategory(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '';
  if (n < 6) return 'calm';
  if (n < 20) return 'light breeze';
  if (n < 39) return 'moderate breeze';
  if (n < 50) return 'fresh breeze';
  if (n < 62) return 'strong wind';
  if (n < 75) return 'near gale';
  if (n < 89) return 'gale';
  return 'storm';
}

function round(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(n * 10) / 10 : null;
}

const httpRequest = this.helpers.httpRequest.bind(this.helpers);

let days = Number(input.days);
if (!Number.isFinite(days) || days < 1) days = 1;
days = Math.min(Math.round(days), 7);

let place = ZAGAZIG;
const wanted = input.location === null || input.location === undefined ? '' : String(input.location).trim();
if (wanted) {
  try {
    const geocodeUrl = 'https://geocoding-api.open-meteo.com/v1/search?name=' + encodeURIComponent(wanted) + '&count=1&language=en&format=json';
    const geocode = await httpRequest({ method: 'GET', url: geocodeUrl, json: true, timeout: 20000 });
    const hit = geocode && Array.isArray(geocode.results) ? geocode.results[0] : null;
    if (!hit) {
      return [{ json: { ok: false, error: 'Location not found for "' + wanted + '". Try a clearer city name.' } }];
    }
    place = {
      lat: hit.latitude,
      lon: hit.longitude,
      name: hit.name + (hit.country ? ', ' + hit.country : ''),
    };
  } catch (error) {
    return [{ json: { ok: false, error: 'Could not search for the location: ' + (error && error.message ? error.message : String(error)) } }];
  }
}

const url = 'https://api.open-meteo.com/v1/forecast?latitude=' + place.lat + '&longitude=' + place.lon
  + '&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_gusts_10m'
  + '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max,sunrise,sunset'
  + '&temperature_unit=celsius&wind_speed_unit=kmh&timezone=Africa%2FCairo&forecast_days=' + days;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let lastError = null;
let data = null;
for (let attempt = 1; attempt <= 3; attempt += 1) {
  try {
    const response = await httpRequest({ method: 'GET', url, json: true, timeout: 30000 });
    if (response && response.current && response.daily) {
      data = response;
      break;
    }
    lastError = new Error('The weather service returned an unexpected response.');
  } catch (error) {
    lastError = error;
  }
  if (attempt < 3) await sleep(1200 * attempt);
}
if (!data) {
  return [{ json: { ok: false, error: 'Could not fetch weather after 3 attempts: ' + (lastError && lastError.message ? lastError.message : String(lastError)) } }];
}

const current = data.current;
const daily = data.daily;
const forecast = (daily.time || []).map((date, index) => {
  const windMax = daily.wind_speed_10m_max ? daily.wind_speed_10m_max[index] : null;
  const gustMax = daily.wind_gusts_10m_max ? daily.wind_gusts_10m_max[index] : null;
  return {
    date: date,
    desc: describe(daily.weather_code[index]),
    min: round(daily.temperature_2m_min[index]),
    max: round(daily.temperature_2m_max[index]),
    rain_chance: daily.precipitation_probability_max ? daily.precipitation_probability_max[index] : null,
    wind_speed_max: round(windMax),
    wind_category: windCategory(windMax),
    wind_description: windCategory(windMax),
    wind_gusts_max: round(gustMax),
    sunrise: daily.sunrise ? daily.sunrise[index] : null,
    sunset: daily.sunset ? daily.sunset[index] : null,
  };
});

return [{
  json: {
    ok: true,
    location: place.name,
    units: { temperature: 'C', wind: 'km/h' },
    current: {
      time: current.time,
      temp: round(current.temperature_2m),
      feels_like: round(current.apparent_temperature),
      humidity: round(current.relative_humidity_2m),
      wind: round(current.wind_speed_10m),
      wind_gust: round(current.wind_gusts_10m),
      wind_category: windCategory(current.wind_speed_10m),
      wind_description: windCategory(current.wind_speed_10m),
      precip: round(current.precipitation),
      desc: describe(current.weather_code),
    },
    forecast: forecast,
  },
}];
